-- 20260601_rmp_vol3_vol1_callouts_and_rules.sql
--
-- Restores the city-level callouts (SDZ corridors, heritage zones, NGT drainage
-- classification, regional parks, peripheral ring road) PLUS substantive zoning
-- rule narratives extracted from RMP 2031 Volume-3 (Master Plan Document,
-- 432K chars / 209pp) and Volume-1 (Vision Document, 107K chars / 51pp).
--
-- Closes the deferred callouts gap from PR A3 (the Land Use Insight PR shipped
-- 2015→2031 shares + landmarks + adjacent PAs only, leaving SDZ/heritage/NGT/PRR
-- empty). Together with the Vol-4 PDR demographics (PR A2), Vol-2 UAV rate
-- card (PR A1), and Vol-Land-Use shares (PR A3), this completes Phase A.
--
-- Extraction: scripts/extract-rmp-volume-facts.py — one Gemini call per volume
-- with strict-JSON schema. ~$0.04 total spend. The script normalises Gemini's
-- occasional fact_key variants into the canonical taxonomy
-- masterplan.service.js → getLandUseIntelligence / getDistrictIntelligence
-- consume.
--
-- Coverage:
--   sdz.special_development_zones              — 5 SDZ corridors (Vol-3 p.88)
--   heritage.heritage_zones                    — 12 heritage zones (Vol-3 p.145)
--   environmental.regional_parks               — regional parks aggregate (Vol-3 p.123)
--   environmental.ngt_drainage_classification  — NGT buffer/drain classification (Vol-1 p.23)
--   road_network.peripheral_ring_road          — PRR alignment + length (Vol-1 p.25)
--   rmp_table.zoning_rule_narratives           — 17 substantive zoning rule narratives (Vol-3 p.84)
--
-- Confidence 0.85 (Gemini text extraction over authoritative gazette text).
-- review_status='pending' so all rows land in the Review Queue for human
-- verification before being quoted in IC memos.
--
-- Volume-6 zoning regulations not in this PR — that source's heritage list
-- hit Gemini's output-token budget on the full inventory pass. Needs a
-- narrower prompt or chunked extraction in a follow-up.
--
-- Idempotent — re-runs DELETE any prior fact at these exact (fact_type,
-- fact_key) tuples before re-INSERTing the canonical set.

BEGIN;

-- Idempotency: clean-slate the callout + rule facts we're seeding.
DELETE FROM regulatory_data.evidence_facts
WHERE (fact_type = 'sdz'           AND fact_key = 'special_development_zones')
   OR (fact_type = 'heritage'      AND fact_key = 'heritage_zones')
   OR (fact_type = 'environmental' AND fact_key IN ('regional_parks', 'ngt_drainage_classification'))
   OR (fact_type = 'road_network'  AND fact_key = 'peripheral_ring_road')
   OR (fact_type = 'rmp_table'     AND fact_key = 'zoning_rule_narratives');

INSERT INTO regulatory_data.evidence_facts
  (source_id, fact_type, fact_key, fact_value, page_number, source_section, confidence_score, review_status)
